using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Talent;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class TrainingBudgetSummaryTests
{
 class User(bool manage=true):ICurrentUser{public string Email=>"budget@example.local";public int? EmployeeId=>6;public int UserId=>6;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>manage&&p==Perm.TalentManage;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static TalentService S(AppDbContext d,bool manage=true){var u=new User(manage);var c=new AppClock(TimeProvider.System);return new(d,u,new AccessScope(d,u),c,new AuditService(d,u,c),new NotificationService(d,u,c));}
 static TrainingCourse Course(string state,decimal? estimate,string currency="EGP",DateTime? date=null)=>new(){Title="Fictional budget course",Hours=4,Date=date??new(2028,1,1),ApprovalStatus=state,PlannedBudget=estimate,Currency=currency};
 [Fact]public async Task SeparatesCurrencyAndStateAndCountsEachCourseOnce(){await using var d=await Db();var first=Course("Approved",123.45m);d.AddRange(first,Course("Approved",10.55m),Course("Pending",70m),Course("Rejected",80m),Course("Approved",90m,"USD"),Course("Legacy",5m));await d.SaveAsync();d.AddRange(new TrainingEnrollment{CourseId=first.Id,EmployeeId=6},new TrainingEnrollment{CourseId=first.Id,EmployeeId=4});await d.SaveAsync();var v=await S(d).TrainingBudgetAsync(2028);Assert.Equal(6,v.Courses);Assert.Equal(0,v.MissingEstimates);Assert.Equal(5,v.Rows.Count);var approved=Assert.Single(v.Rows.Where(x=>x.ApprovalStatus=="Approved"&&x.Currency=="EGP"));Assert.Equal(134m,approved.Estimate);Assert.Equal(2,approved.CoursesWithEstimate);Assert.Equal(90m,Assert.Single(v.Rows.Where(x=>x.Currency=="USD")).Estimate);Assert.Equal(70m,Assert.Single(v.Rows.Where(x=>x.ApprovalStatus=="Pending")).Estimate);Assert.Equal(80m,Assert.Single(v.Rows.Where(x=>x.ApprovalStatus=="Rejected")).Estimate);}
 [Fact]public async Task MissingInvalidAndZeroEstimatesAreNotConflated(){await using var d=await Db();d.AddRange(Course("Approved",null),Course("Pending",20m,""),Course("Legacy",30m,"egp"),Course("Approved",-1m),Course("Approved",0m));await d.SaveAsync();var v=await S(d).TrainingBudgetAsync(2028);Assert.Equal(5,v.Courses);Assert.Equal(4,v.MissingEstimates);var row=Assert.Single(v.Rows);Assert.Equal(0m,row.Estimate);Assert.Equal(1,row.CoursesWithEstimate);}
 [Fact]public async Task ScheduledCalendarYearIsExclusiveAtNextYearAndResultIsReadOnly(){await using var d=await Db();var a=Course("Approved",12.34m,date:new(2028,12,31,23,59,59));d.AddRange(a,Course("Approved",99m,date:new(2029,1,1)),Course("Approved",88m,date:new(2027,12,31)));await d.SaveAsync();var audits=await d.Set<AuditLog>().CountAsync();var v=await S(d).TrainingBudgetAsync(2028);Assert.Equal(1,v.Courses);Assert.Equal(12.34m,Assert.Single(v.Rows).Estimate);v.Rows.Clear();Assert.Equal(12.34m,a.PlannedBudget);Assert.Equal(audits,await d.Set<AuditLog>().CountAsync());Assert.Equal(3,await d.Set<TrainingCourse>().CountAsync(x=>x.Title=="Fictional budget course"));}
 [Fact]public async Task EmployeeCannotReadPlanningAndYearsAreBounded(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d,false).TrainingBudgetAsync(2028));foreach(var year in new[]{0,1999,9999})await Assert.ThrowsAsync<DomainException>(()=>S(d).TrainingBudgetAsync(year));var v=await S(d).TrainingBudgetAsync(9998);Assert.Empty(v.Rows);Assert.Equal(0,v.Courses);Assert.Equal(0,v.MissingEstimates);}
 [Fact]public async Task UnknownStateIsNeverPromotedToApproval(){await using var d=await Db();d.Add(Course("ExternalUnknown",42m));await d.SaveAsync();var v=await S(d).TrainingBudgetAsync(2028);Assert.Equal("Legacy",Assert.Single(v.Rows).ApprovalStatus);Assert.Equal("ExternalUnknown",(await d.Set<TrainingCourse>().SingleAsync(x=>x.Title=="Fictional budget course")).ApprovalStatus);}
}
